#[cfg(feature = "napi-bindings")]
impl ::napi::bindgen_prelude::FromNapiValue for TriviaTransport {
    unsafe fn from_napi_value(
        env: ::napi::sys::napi_env,
        napi_val: ::napi::sys::napi_value,
    ) -> ::napi::Result<Self> {
        match ::sittir_core::slot::transport_value_type(env, napi_val)? {
            ::napi::ValueType::Number => {
                match u16::from_napi_value(env, napi_val)? {
                    337 => Ok(Self::LineComment(LineCommentTransport::from_napi_value(env, napi_val)?)),
                    340 => Ok(Self::BlockComment(BlockCommentTransport::from_napi_value(env, napi_val)?)),
                    169 => Ok(Self::Space(SpaceTransport::from_napi_value(env, napi_val)?)),
                    170 => Ok(Self::Tab(TabTransport::from_napi_value(env, napi_val)?)),
                    171 => Ok(Self::Newline(NewlineTransport::from_napi_value(env, napi_val)?)),
                    172 => Ok(Self::Blankline(BlanklineTransport::from_napi_value(env, napi_val)?)),
                    173 => Ok(Self::DoubleBlankline(DoubleBlanklineTransport::from_napi_value(env, napi_val)?)),
                    other => Err(::napi::Error::from_reason(format!(
                        "unknown kind id {other} in TriviaTransport",
                    ))),
                }
            }
            ::napi::ValueType::Object => {
                let obj = ::napi::bindgen_prelude::Object::from_napi_value(env, napi_val)?;
                let kind_id: u16 = obj.get("$type")?.ok_or_else(||
                    ::napi::Error::from_reason("$type property missing in TriviaTransport")
                )?;
                let text: Option<String> = obj.get("$text")?;
                match kind_id {
                    id if id == ::sittir_core::types::KindId::ERROR.0 => Ok(Self::Verbatim(VerbatimTransport {
                        text: obj.get("$text")?.ok_or_else(|| ::napi::Error::from_reason("ERROR node without $text in TriviaTransport"))?,
                    })),
                    337 if text.is_some() => Ok(Self::Text(::sittir_core::trivia::TriviaText { kind: ::sittir_core::types::KindId(337), text: text.unwrap_or_default() })),
                    340 if text.is_some() => Ok(Self::Text(::sittir_core::trivia::TriviaText { kind: ::sittir_core::types::KindId(340), text: text.unwrap_or_default() })),
                    337 => Ok(Self::LineComment(LineCommentTransport::from_napi_value(env, napi_val)?)),
                    340 => Ok(Self::BlockComment(BlockCommentTransport::from_napi_value(env, napi_val)?)),
                    169 => Ok(Self::Space(SpaceTransport::from_napi_value(env, napi_val)?)),
                    170 => Ok(Self::Tab(TabTransport::from_napi_value(env, napi_val)?)),
                    171 => Ok(Self::Newline(NewlineTransport::from_napi_value(env, napi_val)?)),
                    172 => Ok(Self::Blankline(BlanklineTransport::from_napi_value(env, napi_val)?)),
                    173 => Ok(Self::DoubleBlankline(DoubleBlanklineTransport::from_napi_value(env, napi_val)?)),
                    other => Err(::napi::Error::from_reason(format!(
                        "unknown kind id {other} in TriviaTransport",
                    ))),
                }
            }
            ::napi::ValueType::String => Ok(Self::Verbatim(VerbatimTransport { text: String::from_napi_value(env, napi_val)? })),
            _ => Err(::napi::Error::from_reason("TriviaTransport: expected u16 kind_id, string, or object with $type")),
        }
    }
}

