fn render_source_file(node: &SourceFileTransport, w: &mut dyn ::sittir_core::render::RenderSink) -> ::sittir_core::render::RenderResult {
    let shebang = View::new(&node.shebang, "{}");
    let statements = ListView {
        items: node.statements.as_deref().unwrap_or(&[]),
        template: "{}",
        token: "",
        before: 0,
        after: node.statements_separator_space.unwrap_or(0),
        leading: false,
        trailing: false,
        head: Some(options::SITE_SOURCE_FILE_STATEMENTS_START),
        tail: Some(options::SITE_SOURCE_FILE_STATEMENTS_END),
    };
    w.edge(::sittir_core::types::KindId(176), ::sittir_core::options::Side::Before, node.edges.and_then(|e| e.before));
    shebang.render(w)?;
    ::sittir_core::trivia::render_inner(&node.transport_trivia_data, "statements", w)?;
    statements.render(w)?;
    w.edge(::sittir_core::types::KindId(176), ::sittir_core::options::Side::After, node.edges.and_then(|e| e.after));
    Ok(())
}

